-- Sprint 1 (docs/improvements/HOME-HERO-PLAN.md §7, D-030, D-032): the home hero's photograph, as data.
-- Generated by scripts/build-hero-photos.mjs from one original (not committed); the two crops are
-- design/hero/hero-desktop.webp and hero-mobile.webp. Each is added as the current photo of its slot
-- only if the slot is empty — the owner replaces either in Admin → Photos at any time (the old one is
-- kept, BR-1.17). The credit is the "home-hero" block's, shown on the image. The hero itself stays off
-- until the flag home.hero_v2 is switched on. Additive only.

INSERT INTO "ProfilePhoto" ("id", "purpose", "altText", "mimeType", "width", "height", "byteSize", "sha256", "fileData")
SELECT gen_random_uuid()::text, 'hero-desktop', 'Johannesburg at dusk: a skyline of lit towers under a purple sky and an orange horizon', 'image/webp', 2560, 1097, 90682, 'd0f33a917f235ad2b61a22c33f18fb92b64bc493e97c8908d87a834efdf7f322', decode('', 'base64')
WHERE NOT EXISTS (SELECT 1 FROM "ProfilePhoto" WHERE "purpose" = 'hero-desktop');

INSERT INTO "ProfilePhoto" ("id", "purpose", "altText", "mimeType", "width", "height", "byteSize", "sha256", "fileData")
SELECT gen_random_uuid()::text, 'hero-mobile', 'Johannesburg at dusk: a skyline of lit towers under a purple sky and an orange horizon', 'image/webp', 1169, 1462, 58636, '968e7b21a451d29466e3e50db13cc04518d954dc4ebdbe8ad66d4f820feb03fa', decode('', 'base64')
WHERE NOT EXISTS (SELECT 1 FROM "ProfilePhoto" WHERE "purpose" = 'hero-mobile');

UPDATE "SiteContent"
SET "body" = "body" || jsonb_build_object('imageCredit', 'Photo: Tania Melnyczuk · Unsplash', 'imageCreditUrl', 'https://unsplash.com/photos/city-skyline-during-night-time-diwubNzqQW0')
WHERE "key" = 'home-hero' AND NOT ("body" ? 'imageCredit');
